      writeConfig('''
provider: chatgpt-codex
model: mock-model
baseUrl: ${server.baseUrl}
mode: code
approvalMode: yolo
''');

      final result = await runFa(
        'say something',
        extraEnv: const {'CHATGPT_OAUTH_CREDENTIALS': 'dummy-creds'},
      );

      expect(result.exitCode, 0, reason: result.output);
      expect(
        result.stderr,
