        contains('chatgpt-codex'),
      );
    });

    test('E3: a roles chain on the unknown provider degrades to the '
        'legacy model instead of failing the boot', () async {
      writeConfig('''
provider: openai-completions
model: mock-model
baseUrl: ${server.baseUrl}
mode: code
approvalMode: yolo
roles:
